mapper.delete:
DELETE FROM review
WHERE v_idx  = #{revIdx}
  AND u_idx  = #{userIdx}

mapper.select:
SELECT r.v_idx, r.s_idx, r.u_idx, r.v_parent_idx, r.v_content, r.v_rating, IFNULL(u.u_name, '알 수 없음') AS u_name, s.s_name, r.v_created_at, r.v_img, (SELECT COUNT(*) FROM review_report rr WHERE rr.v_idx = r.v_idx) AS report_count FROM review r LEFT JOIN user u ON r.u_idx = u.u_idx LEFT JOIN space s ON r.s_idx = s.s_idx WHERE r.v_parent_idx = 0
AND (u.u_name LIKE CONCAT('%', #{searchWord}, '%') OR s.s_name LIKE CONCAT('%', #{searchWord}, '%') OR r.v_content LIKE CONCAT('%', #{searchWord}, '%'))
ORDER BY r.v_idx DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM reservation
WHERE u_idx    = #{userIdx}
  AND s_idx    = #{spcIdx}
  AND r_status = 'FINISH'
